{
  "scholarshipName": "University of Auckland Doctoral Scholarship",
  "scholarshipAmount": "35468",
  "scholarshipType": "Amount",
  "scholarshipMetaData": [
    {
      "title": "Scholarships",
      "text": "Supports excellent domestic and international doctoral candidates whose research aligns with the strategic objectives of the University of Auckland."
    },
    {
      "title": "Term",
      "text": "up to 42 months of full-time equivalent enrolment."
    },
    {
      "title": "Application",
      "text": "no separate application is required. Applicants indicate in their doctoral application that they wish to be considered."
    },
    {
      "title": "Selection",
      "text": "based on alignment with the strategic objectives of the University and the relevant faculty or research institute."
    },
    {
      "title": "Eligibility",
      "text": "applicant must be a domestic student, or an international student who is eligible to pay domestic fees for the doctoral programme."
    },
    {
      "title": "Eligibility",
      "text": "applicant must not already hold a doctorate or have previously received payment for a University of Auckland Doctoral Scholarship."
    },
    {
      "title": "Eligibility",
      "text": "applicant must not be enrolled in a doctoral programme, except for approved transfers."
    }
  ]
}
